export const BODY: string = "\n<p>الحد إطار حول صورة: يفصل الصورة عما حولها ويضيف لمسة أخيرة ويمنح الصورة إحساسًا بالاكتمال.</p>\n<p>كانت الحدود جزءًا من التصوير منذ البداية: المطبوعات كانت تُركب على ورق مقوى والشرائح كانت تُحفظ في إطارات، واليوم حد رقمي يقوم بنفس العمل على الشاشة.</p>\n<p>يشرح هذا الدليل كيف تعمل الحدود وأي أنماط تختار وكيف تستخدمها جيدًا: يغطي حدودًا صلبة وأنماط Polaroid وإطارات بتوهج متدرج وظلالًا واختيارات لون.</p>\n<h2 id=\"what-is-a-border\">ما حد الصورة؟</h2>\n<p>الحد شريط لون أو نمط مضاف حول حواف صورة: يذهب خارج الصورة نفسها، فلا يغطي أي جزء من الصورة.</p>\n<p>تخدم الحدود غرضين: تزيّن الصورة، مانحة إياها مظهرًا منتهيًا، وتفصلها عن الخلفية، ما يساعدها على البروز في صفحة مزدحمة. والحد مختلف عن القص: القص يزيل بكسلات من الحواف، بينما الحد يضيف بكسلات حولها، جاعلًا الصورة الأخيرة أكبر قليلًا.</p>\n<p>فكر في حد كإطار على جدار: الإطار لا يغيّر اللوحة، لكنه يغيّر كيف تبدو اللوحة، وإطار جيد يجعل العمل يبدو أفضل.</p>\n<h2 id=\"solid-borders\">حدود صلبة: الإطار الكلاسيكي</h2>\n<p>حد صلب شريط بلون واحد بعرض موحد حول الصورة: إنه أبسط نمط، ويناسب تقريبًا أي صورة، من صور شخصية إلى صور منتج.</p>\n<p>الحدود البيضاء هي الأكثر شيوعًا: تمنح الصورة إحساس معرض نظيف، وتعمل على أي خلفية، لأن الأبيض يفصل الصورة عن الصفحة. والحدود السوداء تبدو أكثر درامية: تناسب صور مزاج داكن ولقطات ليلية وفنًا، حيث يضيف الإطار الداكن وزنًا وتركيزًا إلى الصورة.</p>\n<p>حدود ملونة قد تطابق علامة أو سمة: حد باستيل ناعم يناسب صورة زفاف، بينما لون جريء يناسب ملصقًا أو رسم عرض.</p>\n<h2 id=\"polaroid-style\">نمط Polaroid: المفضل الرجعي</h2>\n<p>يحاكي حد Polaroid مظهر الفيلم الفوري: إطار أبيض بشريط أسمك في الأسفل. ويبدو حنينًا وعفويًا وممتعًا، ولهذا يناسب صور العطلات ولقاءات الأصدقاء.</p>\n<p>الشريط السفلي السميك هو توقيع النمط: يعطي مساحة لتعليق مكتوب بخط اليد أو تاريخ أو ملاحظة قصيرة، مثل طباعة Polaroid حقيقية. وتعمل حدود Polaroid أفضل في صور عفوية وشخصية: تبدو خارج مكانها في صورة شخصية رسمية أو صورة منتج، حيث حد صلب نظيف أكثر ملاءمة.</p>\n<p>يشمل <a href=\"/ar/idafa-itar-ila-as-sura/\">مولد حدود الصور</a> نمط Polaroid كأحد خيارات حده: يطبق الشكل الكلاسيكي تلقائيًا، بما فيه الشريط السفلي الأعرض.</p>\n<h2 id=\"gradient-glow\">إطارات بتوهج متدرج</h2>\n<p>يمزج إطار بتوهج متدرج لونين أو أكثر حول الصورة، خالقًا حدًا ناعمًا ومشرقًا: يبدو حديثًا ورقميًا، ويناسب رسومًا اجتماعية وملصقات.</p>\n<p>يُحسب التوهج من زاوية ومجموعة ألوان: تغيير الزاوية يحرك المزج حول الإطار، فالألوان نفسها قد تنتج مظاهر كثيرة مختلفة. وتعمل الإطارات المتدرجة جيدًا في صور داكنة، حيث يضيف الحد الساطع طاقة: وقد تطغى على صورة فاتحة وجيدة التهوية، فاستخدمها عندما تحتاج الصورة دراما.</p>\n<p>أبقِ التوهج لطيفًا لعمل احترافي: تدرج ناعم يضيف صقلًا، بينما توهج قوي وساطع يشتت عن الصورة نفسها.</p>\n<h2 id=\"border-size\">حجم الحد: من 1 بالمئة إلى 25 بالمئة</h2>\n<p>يُثبت حجم الحد كنسبة مئوية من الصورة، من 1 بالمئة إلى 25 بالمئة: حد صغير خط رفيع، بينما حد كبير يصبح passepartout عريضًا.</p>\n<p>حد رفيع 1 إلى 3 بالمئة يناسب معظم الصور: يؤطر الصورة دون سرقة الانتباه، ويعمل بأي حجم عرض. وحد متوسط 5 إلى 10 بالمئة يخلق إحساس معرض: يمنح الصورة مساحة للتنفس ويناسب مطبوعات ومحافظ وشرائح عرض.</p>\n<p>حد كبير فوق 15 بالمئة يصبح بيان تصميم: يناسب ملصقات ورسومًا اجتماعية، حيث الإطار جزء من المظهر لا مجرد حد.</p>\n<h2 id=\"frame-radius-vs-photo-radius\">نصف قطر الإطار مقابل نصف قطر الصورة</h2>\n<p>يتحكم نصف قطر الإطار في استدارة الحافة الخارجية للحد، بينما يتحكم نصف قطر الصورة في استدارة الحافة الداخلية حيث يلتقي الحد بالصورة.</p>\n<p>تثبيت الاثنين على نفس القيمة يعطي إطارًا مدورًا موحدًا: تثبيتهما بشكل مختلف يخلق حدًا سميكًا في وسط كل جانب ورفيعًا عند الزوايا. ولإطار مدور بسيط، ثبّت نصفي القطر على نفس الرقم: النتيجة منحنى نظيف ومتسق يبدو احترافيًا في بطاقات ومنشورات اجتماعية.</p>\n<p>ولنمط Polaroid، أبقِ نصفي القطر منخفضين: المظهر الكلاسيكي للفيلم الفوري له زوايا مربعة، وتدويرها أكثر مما يلزم يكسر الإحساس الرجعي.</p>\n<h2 id=\"drop-shadows\">ظلال منسدلة: كيف تضيف عمقًا</h2>\n<p>يضيف ظل منسدل حدًا داكنًا ناعمًا خلف الصورة المؤطرة، ما يجعلها تبدو عائمة فوق الصفحة: يضيف عمقًا وإحساسًا بالصقل.</p>\n<p>تعمل الظلال أفضل على خلفيات فاتحة، حيث الحد الداكن مرئي: على خلفية داكنة، يندمج الظل ويضيف قليلًا إلى الصورة. وتختفي الظلال المنسدلة عندما تصدّر كـJPG: ليس لـJPG شفافية، فالظل، الذي يحتاج خلفية شفافة ليُعرض، لا يمكن حفظه بتلك الصيغة.</p>\n<p>صدّر كـPNG أو WebP للحفاظ على الظل: تدعم الصيغتان الشفافية، فينجو الظل من التصدير ويُعرض جيدًا على أي خلفية.</p>\n<h2 id=\"colour-choices\">كيف تختار ألوان الحد</h2>\n<p>الأبيض هو أكثر لون حد أمانًا: يناسب أي صورة ويعمل على أي خلفية ويمنح الصورة إحساس معرض نظيف لا يبدو قديمًا أبدًا.</p>\n<p>الأسود هو ثاني أكثر لون أمانًا: يضيف دراما وتركيزًا، ويناسب صور مزاج داكن ولقطات ليلية وفنًا، حيث حد فاتح سيبدو خارج مكانه. وطابق الحد مع لون من الصورة لمظهر مصمم: حد يأخذ لون فستان أو سماء أو منتج يربط الإطار بالصورة.</p>\n<p>تجنب حدودًا ساطعة ومشبعة في صور جدية: إطار نيون في صورة زفاف يبدو كخطأ، بينما إطار محايد ناعم يبدو مقصودًا.</p>\n<h2 id=\"quick-frame-presets\">إعدادات إطار سريعة مسبقة</h2>\n<p>تشمل الأداة أربعة إعدادات إطار سريعة مسبقة، كل منها يضبط نمط الحد والحجم واللون والظل بنقرة واحدة: إنها نقطة بداية سريعة لأي صورة.</p>\n<p>الإعدادات المسبقة ليست ثابتة: بعد النقر على واحد، تستطيع تغيير أي ضبط، بما فيه لون الإطار أو الحجم أو الظل، ليناسب صورتك. واستخدم الإعدادات المسبقة لاستكشاف الأنماط بسرعة: انقر عليها وانظر أيها يناسب صورتك، ثم اضبط القيم من هناك.</p>\n<p>ولمظهر متسق عبر مجموعة صور، استخدم نفس الإعداد المسبق لكلها: دفعة صور بإطارات متطابقة تبدو كسلسلة، بينما إطارات مختلطة تبدو عشوائية.</p>\n<h2 id=\"borders-for-social\">حدود للتواصل الاجتماعي</h2>\n<p>تساعد الحدود صورة على البروز في خلاصة مزدحمة: حد أبيض يفصل الصورة عن المنشورات حولها، وتتجه العين إلى الصورة المؤطرة.</p>\n<p>أبقِ الحدود الاجتماعية رفيعة: حد سميك يشغل مساحة في معاينة خلاصة صغيرة، تاركًا مكانًا أقل للصورة نفسها، وهي ما جاء الناس لرؤيته. واستخدم نمط حد متسقًا عبر منشوراتك: إطار مميز يصبح جزءًا من هويتك البصرية، ويبدأ المتابعون في اكتشاف منشوراتك قبل قراءة اسمك.</p>\n<p>راجع الصورة ذات الحد بحجم خلاصة: حد يبدو جيدًا بالحجم الكامل قد يهيمن على معاينة صغيرة، فاختبر قبل النشر.</p>\n<h2 id=\"borders-for-print\">حدود للطباعة</h2>\n<p>استخدمت الصور المطبوعة حدودًا لأكثر من قرن، وحد رقمي يجهّز صورة لنفس المعاملة: حد أبيض حول طباعة يمنحها إحساس معرض.</p>\n<p>للمطبوعات، استخدم حدًا متوسطًا 5 إلى 10 بالمئة: المساحة الإضافية تمنح الطباعة مكانًا للتنفس، وتعطي هامشًا للتعامل دون لمس الصورة. وراجع حجم الطباعة قبل إضافة حد: حد يضيف إلى الأبعاد الكلية، فصورة ذات حد تحتاج حجم ورق أكبر من نفس الصورة دونه.</p>\n<p>ولطباعة مؤطرة، الحد جزء من التصميم: حد أبيض داخل إطار داكن يخلق تأثير passepartout، وهو العرض الكلاسيكي للمعرض.</p>\n<h2 id=\"borders-for-products\">حدود لصور المنتج</h2>\n<p>تحتاج صور المنتج تأطيرًا متسقًا، لأن صفحة متجر بحدود غير متساوية تبدو مهملة: استخدم نفس نمط الحد وحجمه لكل صورة منتج.</p>\n<p>حد أبيض رفيع يناسب معظم المنتجات: يفصل العنصر عن خلفية الصفحة دون تشتيت عن المنتج نفسه. وتجنب حدودًا ملونة في صور المنتج إلا إذا كان اللون جزءًا من علامتك: إطار ساطع قد يتعارض مع المنتج ويجعل القائمة تبدو غير احترافية.</p>\n<p>ولعرض أو ترويج، قد يبرز حد ملون العرض: إطار أحمر أو ذهبي حول منتج مخفض يجذب الانتباه، وهو هدف الترويج.</p>\n<h2 id=\"transparency-and-formats\">شفافية وصيغ وتصدير</h2>\n<p>تُظهر الأداة رقعة شطرنج رمادية وبيضاء حول الإطار في المعاينة: ذلك النمط يعني شفافية، لا خلفية رمادية، ويُظهر أين الصورة شفافة.</p>\n<p>التصدير كـPNG أو WebP يحافظ على الشفافية، بما فيها الزوايا المدورة والظلال المنسدلة. والتصدير كـJPG يسطّح كل شيء فوق خلفية صلبة. ولصورة مؤطرة بزوايا مدورة، اختر PNG أو WebP: تصدير JPG يملأ الزوايا الشفافة بلون صلب، ما يكسر المظهر المدور.</p>\n<p>يظهر منزلق الجودة لتصديرات JPG وWebP ويُخفى لـPNG، لأن PNG دون فقدان وليس له ضبط جودة لتغييره.</p>\n<h2 id=\"borders-vs-frames-vs-matting\">حدود وإطارات وpassepartout: ما الفرق؟</h2>\n<p>الحد شريط لون حول الصورة، مضاف رقميًا. والإطار شيء مادي يحمل طباعة، وpassepartout هو الورق المقوى داخل الإطار الذي يحيط بالصورة.</p>\n<p>تحاكي الحدود الرقمية passepartout: حد أبيض عريض حول صورة يبدو كطباعة ذات passepartout، ولهذا يبدو في مكانه في سياق معرض. وحد رفيع أقرب إلى حافة إطار: يحدد حد الصورة دون إضافة المساحة السخية التي يعطيها passepartout.</p>\n<p>اختر بحسب الإحساس الذي تريده: passepartout يبدو رسميًا ومعرضيًا، بينما إطار رفيع يبدو حديثًا ونظيفًا.</p>\n<h2 id=\"privacy-local-processing\">خصوصية: تأطير دون رفع أي شيء</h2>\n<p>كل عمل الحدود يحدث في متصفحك: صورك لا تُرفع أبدًا إلى خادم، وهو أمر مهم عندما تكون الصور شخصية أو عمل عملاء أو منتجات غير منشورة.</p>\n<p>هذه ميزة حقيقية مقابل محررات السحابة: صورة منتج أو صورة عائلية لا يجب أن تسافر إلى خادم لا تستطيع رؤيته، فقط لإضافة إطار. وتزيل الأداة أيضًا بيانات GPS EXIF عند التصدير: صورة مؤطرة منزلة من الأداة لا تحمل أي سجل لأين التُقطت.</p>\n<p>احتفظ بالصورة الأصلية دون حد: بمجرد أن يندمج حد في تصدير، لا يمكن إزالته من ذلك الملف، فالأصل هو نسختك النظيفة الوحيدة.</p>\n<h2 id=\"common-border-mistakes\">أخطاء شائعة مع الحدود</h2>\n<p>أكثر خطأ شيوعًا حد سميك جدًا: إطار ثقيل يطغى على صورة صغيرة ويترك مكانًا قليلًا للصورة نفسها، وهي ما جاء الناس لرؤيته.</p>\n<p>خطأ آخر لون يتعارض مع الصورة: حد ساطع على صورة ناعمة وباهتة ينافس الصورة على الانتباه ويجعل التصميم كله يبدو سيئًا. وينسى الناس أيضًا أن حدًا يضيف إلى الحجم الكلي: صورة بحد 25 بالمئة أكبر بكثير من الأصل، وقد لا تناسب وجهتها بعد الآن.</p>\n<p>وأخيرًا، لا تستخدم ظلًا منسدلًا مع تصدير JPG وتتوقع أن ينجو: JPG ليس له شفافية، فالظل يختفي والنتيجة تبدو مسطحة.</p>\n<p>للعملية خطوة بخطوة، راجع <a href=\"/ar/blog/kayfiyya-idafa-itar-ila-as-sura/\">كيف تضيف حدًا إلى صورة</a>. ولأفكار النمط، اقرأ <a href=\"/ar/blog/anmat-itur-wa-hawaf-as-suwar/\">إطارات وحدود الصور: أنماط للتواصل الاجتماعي والطباعة</a>، ولتدوير زوايا صورة مؤطرة استخدم <a href=\"/ar/tadweer-zawaya-as-sura/\">أداة تدوير زوايا الصورة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما أفضل لون حد لصورة؟","answer":"الأبيض هو الخيار الأكثر أمانًا: يناسب أي صورة ويعمل على أي خلفية ويعطي إحساس معرض نظيف. والأسود يضيف دراما لصور مزاج داكن أو ليلية. وطابق الحد مع لون من الصورة لمظهر مصمم."},{"question":"هل إضافة حد تغيّر حجم صورتي؟","answer":"نعم، يضيف الحد بكسلات حول الصورة، فالصورة الأخيرة أكبر من الأصل: حد 10 بالمئة في كل جانب يضيف 20 بالمئة إلى العرض والارتفاع. وراجع الأبعاد الأخيرة قبل التصدير."},{"question":"لماذا اختفى ظلي المنسدل بعد التصدير كـJPG؟","answer":"JPG ليس له شفافية، وظل منسدل يحتاج خلفية شفافة ليُعرض: صدّر كـPNG أو WebP، وكلاهما يدعم الشفافية ويحافظ على الظل. وتُظهر رقعة الشطرنج في المعاينة أين الشفافية."},{"question":"ما الفرق بين حد Polaroid وحد صلب؟","answer":"حد Polaroid له شريط أسمك في الأسفل، محاكيًا الفيلم الفوري، مع مساحة لتعليق. وحد صلب شريط موحد بلون واحد في الجوانب الأربعة. ويناسب Polaroid صورًا عفوية، بينما حد صلب يناسب كل شيء تقريبًا."},{"question":"هل يمكنني إضافة حد إلى صورة على هاتفي؟","answer":"نعم، يعمل مولد الحدود في متصفح الهاتف: ارفع من معرضك واختر نمطًا وحجمًا وراجع الإطار ونزّل النتيجة. والإعدادات السريعة المسبقة تجعل تأطير صورة على شاشة صغيرة سهلًا."},{"question":"هل يجب أن تكون لصور المنتج حدود؟","answer":"حد أبيض رفيع غالبًا يساعد، إذ يفصل المنتج عن الصفحة ويجعل القوائم تبدو مرتبة. وأبقِ النمط متطابقًا عبر الكتالوج كله. وتجنب حدودًا ملونة إلا إذا كان اللون جزءًا من علامتك."}];
